CREATE SCHEMA IF NOT EXISTS esquema_comandas;
CREATE TABLE IF NOT EXISTS esquema_comandas.mesas(id_mesa BIGSERIAL PRIMARY KEY,codigo_mesa VARCHAR(20) NOT NULL UNIQUE,nombre_area VARCHAR(60) NOT NULL DEFAULT 'SALON',capacidad SMALLINT NOT NULL DEFAULT 4 CHECK(capacidad>0),estado VARCHAR(20) NOT NULL DEFAULT 'LIBRE' CHECK(estado IN('LIBRE','OCUPADA','FUERA_SERVICIO')),activo BOOLEAN NOT NULL DEFAULT TRUE,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS esquema_comandas.estaciones_cocina(id_estacion_cocina BIGSERIAL PRIMARY KEY,nombre VARCHAR(60) NOT NULL UNIQUE,activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS esquema_comandas.categorias_productos(id_categoria BIGSERIAL PRIMARY KEY,id_categoria_padre BIGINT REFERENCES esquema_comandas.categorias_productos(id_categoria) ON DELETE SET NULL,nombre VARCHAR(80) NOT NULL UNIQUE,descripcion VARCHAR(250),activo BOOLEAN NOT NULL DEFAULT TRUE,orden_visualizacion INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS esquema_comandas.productos(id_producto BIGSERIAL PRIMARY KEY,id_categoria BIGINT NOT NULL REFERENCES esquema_comandas.categorias_productos(id_categoria),id_estacion_cocina BIGINT REFERENCES esquema_comandas.estaciones_cocina(id_estacion_cocina) ON DELETE SET NULL,codigo_producto VARCHAR(40) UNIQUE,nombre VARCHAR(120) NOT NULL,descripcion TEXT,url_imagen TEXT,precio_unitario NUMERIC(12,2) NOT NULL CHECK(precio_unitario>=0),disponible BOOLEAN NOT NULL DEFAULT TRUE,activo BOOLEAN NOT NULL DEFAULT TRUE,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW(),fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ix_productos_categoria_activo ON esquema_comandas.productos(id_categoria,activo,disponible);
CREATE TABLE IF NOT EXISTS esquema_comandas.pedidos(id_pedido BIGSERIAL PRIMARY KEY,codigo_pedido VARCHAR(30) UNIQUE,id_mesa BIGINT NOT NULL REFERENCES esquema_comandas.mesas(id_mesa),id_usuario_mozo BIGINT NOT NULL,codigo_mozo VARCHAR(30) NOT NULL,estado VARCHAR(25) NOT NULL DEFAULT 'BORRADOR' CHECK(estado IN('BORRADOR','ENVIADO_COCINA','EN_PREPARACION','LISTO','ENTREGADO','PENDIENTE_PAGO','PAGADO','ANULADO')),observaciones TEXT,subtotal NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(subtotal>=0),total_descuento NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(total_descuento>=0),importe_total NUMERIC(12,2) NOT NULL DEFAULT 0 CHECK(importe_total>=0),fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW(),fecha_envio TIMESTAMPTZ,fecha_pago TIMESTAMPTZ,fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS ux_pedido_activo_por_mesa ON esquema_comandas.pedidos(id_mesa) WHERE estado IN('BORRADOR','ENVIADO_COCINA','EN_PREPARACION','LISTO','ENTREGADO','PENDIENTE_PAGO');
CREATE TABLE IF NOT EXISTS esquema_comandas.detalles_pedido(id_detalle_pedido BIGSERIAL PRIMARY KEY,id_pedido BIGINT NOT NULL REFERENCES esquema_comandas.pedidos(id_pedido) ON DELETE CASCADE,id_producto BIGINT REFERENCES esquema_comandas.productos(id_producto) ON DELETE SET NULL,nombre_producto VARCHAR(120) NOT NULL,cantidad INTEGER NOT NULL DEFAULT 1 CHECK(cantidad>0),precio_unitario NUMERIC(12,2) NOT NULL CHECK(precio_unitario>=0),observaciones VARCHAR(500),estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE' CHECK(estado IN('PENDIENTE','EN_PREPARACION','LISTO','ENTREGADO','ANULADO')),total_linea NUMERIC(12,2) GENERATED ALWAYS AS(cantidad*precio_unitario) STORED,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW(),fecha_actualizacion TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS ix_detalles_pedido_pedido ON esquema_comandas.detalles_pedido(id_pedido);
CREATE TABLE IF NOT EXISTS esquema_comandas.traslados_mesa(id_traslado_mesa BIGSERIAL PRIMARY KEY,id_pedido BIGINT NOT NULL REFERENCES esquema_comandas.pedidos(id_pedido) ON DELETE RESTRICT,id_mesa_origen BIGINT NOT NULL REFERENCES esquema_comandas.mesas(id_mesa),id_mesa_destino BIGINT NOT NULL REFERENCES esquema_comandas.mesas(id_mesa),id_usuario_traslado BIGINT NOT NULL,motivo VARCHAR(250),fecha_traslado TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(id_mesa_origen<>id_mesa_destino));
CREATE TABLE IF NOT EXISTS esquema_comandas.eventos_pendientes(id_evento BIGSERIAL PRIMARY KEY,tipo_agregado VARCHAR(60) NOT NULL,id_agregado BIGINT NOT NULL,tipo_evento VARCHAR(80) NOT NULL,contenido_evento JSONB NOT NULL,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW(),fecha_publicacion TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS esquema_comandas.registros_auditoria(id_registro_auditoria BIGSERIAL PRIMARY KEY,id_usuario_actor BIGINT,accion VARCHAR(100) NOT NULL,nombre_entidad VARCHAR(80) NOT NULL,id_entidad VARCHAR(100),valores_nuevos JSONB,motivo TEXT,fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE OR REPLACE FUNCTION esquema_comandas.func_sincronizar_estado_mesa() RETURNS TRIGGER LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN UPDATE esquema_comandas.mesas SET estado=CASE WHEN EXISTS(SELECT 1 FROM esquema_comandas.pedidos WHERE id_mesa=OLD.id_mesa AND estado IN('BORRADOR','ENVIADO_COCINA','EN_PREPARACION','LISTO','ENTREGADO','PENDIENTE_PAGO')) THEN 'OCUPADA' ELSE 'LIBRE' END WHERE id_mesa=OLD.id_mesa; RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND OLD.id_mesa IS DISTINCT FROM NEW.id_mesa THEN UPDATE esquema_comandas.mesas SET estado=CASE WHEN EXISTS(SELECT 1 FROM esquema_comandas.pedidos WHERE id_mesa=OLD.id_mesa AND id_pedido<>NEW.id_pedido AND estado IN('BORRADOR','ENVIADO_COCINA','EN_PREPARACION','LISTO','ENTREGADO','PENDIENTE_PAGO')) THEN 'OCUPADA' ELSE 'LIBRE' END WHERE id_mesa=OLD.id_mesa; END IF;
 UPDATE esquema_comandas.mesas SET estado=CASE WHEN EXISTS(SELECT 1 FROM esquema_comandas.pedidos WHERE id_mesa=NEW.id_mesa AND estado IN('BORRADOR','ENVIADO_COCINA','EN_PREPARACION','LISTO','ENTREGADO','PENDIENTE_PAGO')) THEN 'OCUPADA' ELSE 'LIBRE' END WHERE id_mesa=NEW.id_mesa; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_sincronizar_estado_mesa ON esquema_comandas.pedidos;
CREATE TRIGGER trg_sincronizar_estado_mesa AFTER INSERT OR UPDATE OF estado,id_mesa OR DELETE ON esquema_comandas.pedidos FOR EACH ROW EXECUTE FUNCTION esquema_comandas.func_sincronizar_estado_mesa();
INSERT INTO esquema_comandas.estaciones_cocina(nombre) VALUES('COCINA'),('PARRILLA'),('BEBIDAS') ON CONFLICT(nombre) DO NOTHING;
INSERT INTO esquema_comandas.categorias_productos(nombre,descripcion,orden_visualizacion) VALUES('Pollos','Pollos y platos a base de pollo',1),('Bebidas','Bebidas frías y calientes',2),('Guarniciones','Acompañamientos y extras',3),('Combos','Combos y promociones',4) ON CONFLICT(nombre) DO NOTHING;
INSERT INTO esquema_comandas.mesas(codigo_mesa,nombre_area,capacidad) SELECT 'M'||LPAD(n::TEXT,2,'0'),'SALON',4 FROM GENERATE_SERIES(1,12) gs(n) ON CONFLICT(codigo_mesa) DO NOTHING;
